    public void writeNumber(String encodedValue) throws IOException {
        /* 03-Dec-2010, tatu: related to [JACKSON-423], should try to keep as numeric
         *   identity as long as possible
         */
        if (encodedValue == null) {
            _append(JsonToken.VALUE_NULL);
            return;
        }
        // Trim whitespace to handle cases like " 123 "
        String trimmedValue = encodedValue.trim();
        if (trimmedValue.isEmpty()) {
            // Decide how to handle empty string: error or null?
            // For numbers, an empty string is typically an error.
            throw new JsonParseException(null, "Cannot write empty string as a number");
        }

        // Attempt to parse the string to determine the most appropriate numeric type
        // and preserve numeric identity as much as possible.
        // This also acts as validation.
        try {
            if (_forceBigDecimal) {
                _append(JsonToken.VALUE_NUMBER_FLOAT, new BigDecimal(trimmedValue));
            } else {
                // Try to parse as integer types first to preserve precision
                if (trimmedValue.indexOf('.') < 0 && trimmedValue.indexOf('e') < 0 && trimmedValue.indexOf('E') < 0) {
                    // Looks like an integer
                    try {
                        // Try int
                        _append(JsonToken.VALUE_NUMBER_INT, Integer.valueOf(trimmedValue));
                        return;
                    } catch (NumberFormatException e) {
                        // If too large for int, try long
                        try {
                            _append(JsonToken.VALUE_NUMBER_INT, Long.valueOf(trimmedValue));
                            return;
                        } catch (NumberFormatException e2) {
                            // If too large for long, use BigInteger
                            _append(JsonToken.VALUE_NUMBER_INT, new BigInteger(trimmedValue));
                            return;
                        }
                    }
                }
                // If it contains a decimal point or exponent, or failed integer parsing, treat as float/double/BigDecimal
                // Try double first for common cases
                try {
                    _append(JsonToken.VALUE_NUMBER_FLOAT, Double.valueOf(trimmedValue));
                } catch (NumberFormatException e) {
                    // If double fails (e.g., too large or precision issues), use BigDecimal
                    _append(JsonToken.VALUE_NUMBER_FLOAT, new BigDecimal(trimmedValue));
                }
            }
        } catch (NumberFormatException e) {
            // If parsing fails for any numeric type, it's an invalid number string
            throw new JsonParseException(null, "Invalid numeric value: '" + encodedValue + "'", e);
        }
    }
