public Element previousElementSibling() {
    // 1. Handle the case where the element has no parent.
    // An element without a parent cannot have siblings.
    Element parent = parent();
    if (parent == null) {
        return null;
    }

    // 2. Get all children of the parent. These are the potential siblings.
    List<Element> siblings = parent.children();

    // 3. Find the index of the current element within its siblings list.
    // The indexInList method is assumed to return null if 'this' is not found.
    Integer index = indexInList(this, siblings);

    // 4. Validate that the current element was found in its parent's children list.
    // If not found, it indicates an inconsistent DOM structure.
    // Throwing an exception here is consistent with the original Validate.notNull.
    if (index == null) {
        // This scenario implies a corrupted DOM where an element's parent reference
        // is set, but the element itself is not in the parent's children list.
        // Depending on desired robustness, one might return null here instead of throwing.
        // However, given the original Validate.notNull, an exception is maintained.
        throw new IllegalStateException("Current element not found in its parent's children list. DOM inconsistency detected.");
    }

    // 5. If the current element is not the first child (index > 0),
    // return the element at the previous index.
    if (index > 0) {
        return siblings.get(index - 1);
    } else {
        // If index is 0, it means the current element is the first child,
