    List<Node> allChildrenOfParent = parentNode.childNodes();
    if (allChildrenOfParent.isEmpty()) {
        // If the parent has no children (shouldn't happen if 'this' is a child, but good for robustness)
        return new java.util.ArrayList<>();
    }

    // Create a new list to hold the siblings, excluding the current node.
    List<Node> siblings = new java.util.ArrayList<>(allChildrenOfParent.size() - 1);
    for (Node child : allChildrenOfParent) {
        if (child != this) { // Exclude the current node itself
            siblings.add(child);
        }
    }
    return siblings;
