import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.helper.Validate;
import org.jsoup.safety.Whitelist;

public class Cleaner {

    private Whitelist whitelist;

    public Cleaner(Whitelist whitelist) {
        Validate.notNull(whitelist);
        this.whitelist = whitelist;
    }

    // Assuming ElementMeta and other private methods are correctly implemented elsewhere in the class
    // For the purpose of this exercise, I'm focusing on the 'clean' method's logic.
    private int copySafeNodes(Element source, Element dest) {
        // This is a placeholder. The actual implementation would iterate through source's children,
        // call createSafeElement, and append to dest.
        int numDiscarded = 0;
        for (Element sourceChild : source.children()) {
            ElementMeta meta = createSafeElement(sourceChild);
            if (meta.el != null) {
                dest.appendChild(meta.el);
                numDiscarded += meta.numAttribsDiscarded;
                numDiscarded += copySafeNodes(sourceChild, meta.el); // Recursively clean children
            } else {
                numDiscarded++; // Discarded the element itself
                numDiscarded += copySafeNodes(sourceChild, dest); // Try to clean children even if parent is discarded
            }
        }
        return numDiscarded;
    }

    private ElementMeta createSafeElement(Element sourceEl) {
        // This is a placeholder. The actual implementation would check against the whitelist
        // and create a safe element, discarding unsafe attributes.
        // For demonstration, let's assume it always creates a safe element for now.
        if (whitelist.isSafeTag(sourceEl.tagName())) {
            Element safeEl = new Element(sourceEl.tag(), sourceEl.baseUri());
            int discardedAttribs = 0;
            for (org.jsoup.nodes.Attribute attr : sourceEl.attributes()) {
                if (whitelist.isSafeAttribute(sourceEl.tagName(), sourceEl.attributes(), attr)) {
                    safeEl.attributes().put(attr);
                } else {
                    discardedAttribs++;
                }
            }
            return new ElementMeta(safeEl, discardedAttribs);
        }
        return new ElementMeta(null, sourceEl.attributes().size()); // Discard entire element
    }

    // Assuming ElementMeta is an inner class or defined elsewhere
    private static class ElementMeta {
        Element el;
        int numAttribsDiscarded;

        ElementMeta(Element el, int numAttribsDiscarded) {
            this.el = el;
            this.numAttribsDiscarded = numAttribsDiscarded;
        }
    }

    /**
     * Cleans the provided dirty HTML document by removing all unsafe HTML
     * (elements and attributes) based on the Whitelist configured for this Cleaner instance.
     * This method processes both the head and body sections of the document.
     *
     * @param dirtyDocument The document to clean. Must not be null.
     * @return A new, clean Document containing only safe HTML elements and attributes.
     *         The original dirtyDocument is not modified.
     * @throws IllegalArgumentException if dirtyDocument is null.
     */
    public Document clean(Document dirtyDocument) {
        Validate.notNull(dirtyDocument, "dirtyDocument must not be null");

        Document cleanDocument = Document.createShell(dirtyDocument.baseUri());

        // Clean the head section
        copySafeNodes(dirtyDocument.head(), cleanDocument.head());

        // Clean the body section
        copySafeNodes(dirtyDocument.body(), cleanDocument.body());

        return cleanDocument;
