public String title() {
    // Find the first <title> element in the document.
    // HTML5 specifies a single <title> element within the <head>.
    Element titleElement = getElementsByTag("title").first();

    // If a title element is found, extract its text content.
    // The .text() method typically normalizes whitespace.
    // An additional .trim() is applied for explicit normalization,
    // ensuring no leading/trailing whitespace remains.
    if (titleElement != null) {
        return titleElement.text().trim();
    } else {
        // If no <title> element is found, return an empty string.
        return "";
    }
}
